input.lines:
const parts = [];
const gaitFacts = ctx.reported_gait_evidence;
const gaitReported = [...(gaitFacts?.direct ?? []), ...(gaitFacts?.supporting ?? []), ...(gaitFacts?.inferred_from_nodes ?? [])]
  .some(f => (f.question_id === 'gait_instability_reported' && f.value === true)
          || (f.question_id === 'gait_stability' && (f.value === false || (typeof f.value === 'string' && f.value.trim().toUpperCase() === 'NE'))));
if (gaitReported
    && whyEvidencePhrase(ctx) !== 'Uvádíš nejistotu při chůzi.') {
  parts.push('Uvádíš nejistotu při chůzi.');
}
if (ctx.action_fallback?.status === 'SELECTED') {
  const priority = WHY_FOCUS_CS[ctx.system_priority?.node_id];
  if (priority) parts.push(`Aktivita zaměřená na ${priority} teď nesplňuje bezpečnostní podmínky.`);
  else parts.push('Původní aktivita teď nesplňuje bezpečnostní podmínky.');
}
const leverage    = ctx.system_leverage;
const constraint  = ctx.system_constraint;
const action      = ctx.action_context?.selected;

// Read the selected engine nodes; never splice the instruction into WHY.
const leverageSubject   = WHY_SUBJECT_CS[leverage?.node_id]   ?? NODE_LABEL_CS[leverage?.node_id]   ?? null;
const constraintSubject = WHY_SUBJECT_CS[constraint?.node_id] ?? NODE_LABEL_CS[constraint?.node_id] ?? null;

// Use the action's modeled goal branches without inventing a personal goal.
if (leverageSubject) {
  const branches = (action?.goal_impact?.branches ?? []).filter(b => GOAL_BRANCH_CASUAL_CS[b]);
  let goalPhrase;
  if (branches.length === 0) {
    goalPhrase = 'tvůj aktuální zdravotní stav';
  } else if (branches.length === 1) {
    goalPhrase = GOAL_BRANCH_CASUAL_CS[branches[0]];
  } else {
    goalPhrase = GOAL_BRANCH_PAIR_CS[branches.join('+')]
      ?? branches.map(b => GOAL_BRANCH_CASUAL_CS[b]).join(' a ');
  }
  const focus = WHY_FOCUS_CS[leverage?.node_id];
  const evidencePhrase = whyEvidencePhrase(ctx);
  const inferredBalance = leverage.node_id === 'GAIT_INSTABILITY'
    && evidencePhrase?.includes('Samy nepotvrzují nejistotu při běžné chůzi.');
  if (focus) parts.push(evidencePhrase
    ? (leverage.node_id === 'EXCESS_ADIPOSITY'
      ? `${evidencePhrase} Příčinu nejistoty při chůzi neposuzuji. Vycházím ze zadané výšky a hmotnosti. Proto se dnes zaměřujeme na ${focus}.${ctx.action_fallback?.status === 'SELECTED' ? '' : ` Cílem je podpořit ${goalPhrase}.`}`
      : `${evidencePhrase} Proto se dnes zaměřujeme na ${inferredBalance ? 'rovnováhu' : focus}.${ctx.action_fallback?.status === 'SELECTED' ? '' : ` Cílem je podpořit ${goalPhrase}.`}`)
    : `Podle dostupných údajů se teď zaměřujeme na ${focus}. Cílem je podpořit ${goalPhrase}.`);
}

const isRealGaitReport = evidencePhrase === 'Uvádíš nejistotu při chůzi.';
const adiposityGaitDisclaimer = (leverage.node_id === 'EXCESS_ADIPOSITY' && isRealGaitReport)
  ? ' Příčinu nejisté chůze tím neposuzuji.' : '';
if (focus) parts.push(evidencePhrase
  ? `${evidencePhrase} Proto se dnes zaměřujeme na ${inferredBalance ? 'rovnováhu' : focus}.${ctx.action_fallback?.status === 'SELECTED' ? '' : ` Cílem je podpořit ${goalPhrase}.`}${adiposityGaitDisclaimer}`
  : `Podle dostupných údajů se teď zaměřujeme na ${focus}. Cílem je podpořit ${goalPhrase}.`);

